%% Numerical Modeling of BCR-ABL1 Gene Expression Dynamics in CML
% Using Euler's Method and MATLAB ode45
% Variables:
% M(t): BCR-ABL1 mRNA level
% P(t): BCR-ABL1 protein/activity level

clear; clc; close all;

%% Simulation settings
t0 = 0;          % initial time
tf = 50;         % final time
h = 0.1;         % Euler step size
t = t0:h:tf;     % time vector
N = length(t);   % number of time points

%% Initial conditions
M0 = 0.1;        % initial mRNA level
P0 = 0.1;        % initial protein/activity level
Y0 = [M0; P0];   % initial condition vector for ode45
ا
%% Parameter sets
% Each row: [km dm kp dp u]
% km: mRNA production rate
% dm: mRNA degradation rate
% kp: protein/activity production rate
% dp: protein/activity degradation rate
% u : treatment inhibition rate

params_normal  = [0.5 0.3 0.6 0.4 0.0];
params_cml     = [2.0 0.2 1.5 0.2 0.0];
params_treated = [2.0 0.2 1.5 0.2 0.8];

%% Solve using Euler's Method
[M_normal_E,  P_normal_E]  = euler_BCR_ABL1(t, h, M0, P0, params_normal);
[M_cml_E,     P_cml_E]     = euler_BCR_ABL1(t, h, M0, P0, params_cml);
[M_treated_E, P_treated_E] = euler_BCR_ABL1(t, h, M0, P0, params_treated);

%% Solve using ode45
[t_normal_ode,  Y_normal_ode]  = ode45(@(t,Y) bcr_abl1_ode(t,Y,params_normal),  [t0 tf], Y0);
[t_cml_ode,     Y_cml_ode]     = ode45(@(t,Y) bcr_abl1_ode(t,Y,params_cml),     [t0 tf], Y0);
[t_treated_ode, Y_treated_ode] = ode45(@(t,Y) bcr_abl1_ode(t,Y,params_treated), [t0 tf], Y0);

%% Figure 1: mRNA level using Euler's Method
figure; %[output:53b772b8]
plot(t, M_normal_E, 'LineWidth', 2); hold on; %[output:53b772b8]
plot(t, M_cml_E, 'LineWidth', 2); %[output:53b772b8]
plot(t, M_treated_E, 'LineWidth', 2); %[output:53b772b8]
xlabel('Time'); %[output:53b772b8]
ylabel('BCR-ABL1 mRNA level, M(t)'); %[output:53b772b8]
title('BCR-ABL1 mRNA Dynamics Using Euler Method'); %[output:53b772b8]
legend('Normal Cell', 'Untreated CML Cell', 'Treated CML Cell'); %[output:53b772b8]
grid on; %[output:53b772b8]

%% Figure 2: Protein/activity level using Euler's Method
figure; %[output:53c07eee]
plot(t, P_normal_E, 'LineWidth', 2); hold on; %[output:53c07eee]
plot(t, P_cml_E, 'LineWidth', 2); %[output:53c07eee]
plot(t, P_treated_E, 'LineWidth', 2); %[output:53c07eee]
xlabel('Time'); %[output:53c07eee]
ylabel('BCR-ABL1 Protein/Activity level, P(t)'); %[output:53c07eee]
title('BCR-ABL1 Protein/Activity Dynamics Using Euler Method'); %[output:53c07eee]
legend('Normal Cell', 'Untreated CML Cell', 'Treated CML Cell'); %[output:53c07eee]
grid on; %[output:53c07eee]

%% Figure 3: mRNA level using ode45
figure; %[output:649ccb3f]
plot(t_normal_ode, Y_normal_ode(:,1), 'LineWidth', 2); hold on; %[output:649ccb3f]
plot(t_cml_ode, Y_cml_ode(:,1), 'LineWidth', 2); %[output:649ccb3f]
plot(t_treated_ode, Y_treated_ode(:,1), 'LineWidth', 2); %[output:649ccb3f]
xlabel('Time'); %[output:649ccb3f]
ylabel('BCR-ABL1 mRNA level, M(t)'); %[output:649ccb3f]
title('BCR-ABL1 mRNA Dynamics Using ode45'); %[output:649ccb3f]
legend('Normal Cell', 'Untreated CML Cell', 'Treated CML Cell'); %[output:649ccb3f]
grid on; %[output:649ccb3f]

%% Figure 4: Protein/activity level using ode45
figure; %[output:209f1d50]
plot(t_normal_ode, Y_normal_ode(:,2), 'LineWidth', 2); hold on; %[output:209f1d50]
plot(t_cml_ode, Y_cml_ode(:,2), 'LineWidth', 2); %[output:209f1d50]
plot(t_treated_ode, Y_treated_ode(:,2), 'LineWidth', 2); %[output:209f1d50]
xlabel('Time'); %[output:209f1d50]
ylabel('BCR-ABL1 Protein/Activity level, P(t)'); %[output:209f1d50]
title('BCR-ABL1 Protein/Activity Dynamics Using ode45'); %[output:209f1d50]
legend('Normal Cell', 'Untreated CML Cell', 'Treated CML Cell'); %[output:209f1d50]
grid on; %[output:209f1d50]

%% Figure 5: Euler vs ode45 comparison for treated CML cell
figure; %[output:28494759]
plot(t, P_treated_E, 'LineWidth', 2); hold on; %[output:28494759]
plot(t_treated_ode, Y_treated_ode(:,2), '--', 'LineWidth', 2); %[output:28494759]
xlabel('Time'); %[output:28494759]
ylabel('BCR-ABL1 Protein/Activity level, P(t)'); %[output:28494759]
title('Euler Method vs ode45 for Treated CML Cell'); %[output:28494759]
legend('Euler Method', 'ode45'); %[output:28494759]
grid on; %[output:28494759]

%% Figure 6: Effect of different treatment strengths
u_values = [0 0.3 0.6 0.9];

figure; %[output:103b3193]
hold on; %[output:103b3193]

for i = 1:length(u_values)
    params_temp = [2.0 0.2 1.5 0.2 u_values(i)];
    [t_temp, Y_temp] = ode45(@(t,Y) bcr_abl1_ode(t,Y,params_temp), [t0 tf], Y0);
    plot(t_temp, Y_temp(:,2), 'LineWidth', 2); %[output:103b3193]
end

xlabel('Time'); %[output:103b3193]
ylabel('BCR-ABL1 Protein/Activity level, P(t)'); %[output:103b3193]
title('Effect of Treatment Strength on BCR-ABL1 Activity'); %[output:103b3193]
legend('u = 0', 'u = 0.3', 'u = 0.6', 'u = 0.9'); %[output:103b3193]
grid on; %[output:103b3193]

%% ---------------- Local Functions ----------------

function [M, P] = euler_BCR_ABL1(t, h, M0, P0, params)

    km = params(1);
    dm = params(2);
    kp = params(3);
    dp = params(4);
    u  = params(5);

    N = length(t);

    M = zeros(1, N);
    P = zeros(1, N);

    M(1) = M0;
    P(1) = P0;

    for n = 1:N-1
        dMdt = km - dm*M(n);
        dPdt = kp*M(n) - dp*P(n) - u*P(n);

        M(n+1) = M(n) + h*dMdt;
        P(n+1) = P(n) + h*dPdt;
    end
end

function dYdt = bcr_abl1_ode(t, Y, params)

    km = params(1);
    dm = params(2);
    kp = params(3);
    dp = params(4);
    u  = params(5);

    M = Y(1);
    P = Y(2);

    dMdt = km - dm*M;
    dPdt = kp*M - dp*P - u*P;

    dYdt = [dMdt; dPdt];
end

